"use client";

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { AlertTriangle, BarChart3, Bot, CheckCircle2, Download, Eye, Loader2, LockKeyhole, RefreshCw, ShieldCheck, WalletCards } from "lucide-react";
import AiProviderDashboard from "./AiProviderDashboard";
import AiSecurityDashboard from "./AiSecurityDashboard";
import styles from "./AiGovernanceDashboard.module.css";

type Row = Record<string, any>;
const sections = ["Overview", "Security & Queue", "Providers", "Models & Pricing", "Privacy", "Budgets", "Token Limits", "Background Requests", "Timeouts & Retries", "Alerts", "Usage & Audit"] as const;
const metadataFields = ["artist", "album", "title", "album_artist", "genres", "release_year", "track_number", "disc_number", "duration", "bpm", "musical_key", "energy", "mood", "danceability", "loudness", "instrumentalness", "acousticness", "popularity", "explicit", "existing_tags", "user_rating", "play_count", "last_played", "date_added", "playlist_position"];
const money = (value: unknown, currency = "USD") => value == null ? "Not available" : new Intl.NumberFormat(undefined, { style: "currency", currency }).format(Number(value));
const number = (value: unknown) => new Intl.NumberFormat().format(Number(value || 0));
class ApiRequestError extends Error { constructor(message: string, public code?: string, public fieldErrors: Record<string, string> = {}, public details: Row = {}) { super(message); this.name = "ApiRequestError"; } }
async function api(url: string, init?: RequestInit) { const response = await fetch(url, { cache: "no-store", ...init }); const body = response.status === 204 ? null : await response.json(); if (!response.ok) throw new ApiRequestError(body?.error?.message || body?.message || "The AI governance request failed.", body?.code || body?.error?.code, body?.field_errors || body?.error?.field_errors || {}, body?.details || body?.error?.details || {}); return body; }

export function AiRequestPreview({ preview }: { preview: Row | null }) {
  if (!preview) return <div className={styles.empty}><Eye size={24}/><p>Run a preview to inspect provider-safe metadata, effective limits, and estimated cost. Previewing never executes a request.</p></div>;
  return <article className={styles.preview} aria-label="AI Request Preview"><h3>AI Request Preview</h3><dl className={styles.previewGrid}><div><dt>Feature</dt><dd>{preview.feature}</dd></div><div><dt>Provider</dt><dd>{preview.provider?.displayName}</dd></div><div><dt>Model</dt><dd>{preview.model}</dd></div><div><dt>Privacy mode</dt><dd>{String(preview.privacyMode).replaceAll("_", " ")}</dd></div><div><dt>Estimated input tokens</dt><dd>≈ {number(preview.limits?.estimatedInputTokens)}</dd></div><div><dt>Maximum output tokens</dt><dd>{number(preview.limits?.maxOutputTokens)}</dd></div><div><dt>Expected cost</dt><dd>Estimate: {money(preview.cost?.expectedEstimatedCost, preview.cost?.currency)}</dd></div><div><dt>Maximum cost</dt><dd>Estimate: {money(preview.cost?.maximumEstimatedCost, preview.cost?.currency)}</dd></div><div><dt>Remaining user budget</dt><dd>{money(preview.remainingBudgets?.user, preview.cost?.currency)}</dd></div><div><dt>Remaining provider budget</dt><dd>{money(preview.remainingBudgets?.provider, preview.cost?.currency)}</dd></div><div><dt>Remaining global budget</dt><dd>{money(preview.remainingBudgets?.global, preview.cost?.currency)}</dd></div><div><dt>Pricing confidence</dt><dd>{preview.cost?.confidence}</dd></div></dl><div className={styles.fieldReport}><div><strong>Shared</strong><p>{preview.privacyReport?.included_fields?.join(", ") || "None"}</p></div><div><strong>Transformed</strong><p>{preview.privacyReport?.transformed_fields?.join(", ") || "None"}</p></div><div><strong>Blocked</strong><p>{preview.privacyReport?.blocked_fields?.join(", ") || "None"}</p></div></div>{preview.privacyReport?.warning && <p className={styles.notice}><AlertTriangle size={16}/>{preview.privacyReport.warning}</p>}<details><summary>Provider-safe payload</summary><pre>{JSON.stringify(preview.sanitizedMetadata, null, 2)}</pre></details></article>;
}

function GlobalPerRequestLimit({ governance, edit, save, busy }: { governance: Row | null; edit: (key: string, value: unknown) => void; save: (changes: Row) => Promise<void>; busy: boolean }) {
  const enabled = governance?.perRequestCostLimitEnabled === true;
  const value = governance?.perRequestCostLimitUsd ?? "";
  const invalid = enabled && (!String(value).trim() || !Number.isFinite(Number(value)) || Number(value) <= 0);
  return <section className="glass-panel"><h2>Per-request cost limit</h2><p>Only enabled limits participate. The strictest enabled global, selected-provider, or user limit wins; missing overrides never become zero.</p><label className={styles.check}><input type="checkbox" checked={enabled} onChange={(event) => edit("perRequestCostLimitEnabled", event.target.checked)}/>Enforce global per-request cost limit</label><label>Maximum estimated cost (USD)<input aria-label="Global per-request cost limit amount" type="number" min="0.000001" step="0.000001" disabled={!enabled} value={value} onChange={(event) => edit("perRequestCostLimitUsd", event.target.value)}/><small>{enabled ? invalid ? "Enter an amount greater than zero." : `Global limit: USD ${Number(value).toFixed(6)}` : "Disabled / Unlimited"}</small></label><button disabled={busy || invalid} onClick={() => void save({ perRequestCostLimitEnabled: enabled, perRequestCostLimitUsd: value === "" ? null : value })}>Save per-request limit</button></section>;
}

function ScopedPerRequestLimitEditors({ providers, providerPolicies, users, userPolicies, onSaved, announce }: { providers: Row[]; providerPolicies: Row[]; users: Row[]; userPolicies: Row[]; onSaved: () => Promise<void>; announce: (text: string, failed?: boolean) => void }) {
  const [providerId, setProviderId] = useState("");
  const [providerEnabled, setProviderEnabled] = useState(false);
  const [providerAmount, setProviderAmount] = useState("");
  const [userId, setUserId] = useState("");
  const [userEnabled, setUserEnabled] = useState(false);
  const [userAmount, setUserAmount] = useState("");
  const [saving, setSaving] = useState(false);
  const invalid = (enabled: boolean, value: string) => enabled && (!value.trim() || !Number.isFinite(Number(value)) || Number(value) <= 0);
  const chooseProvider = (id: string) => { const existing = providerPolicies.find((row) => row.providerConfigId === id); setProviderId(id); setProviderEnabled(existing?.perRequestCostLimitEnabled === true); setProviderAmount(existing?.perRequestCostLimitUsd?.toString() ?? ""); };
  const chooseUser = (id: string) => { const existing = userPolicies.find((row) => row.userId === id); setUserId(id); setUserEnabled(existing?.perRequestCostLimitEnabled === true); setUserAmount(existing?.perRequestCostLimitUsd?.toString() ?? ""); };
  const saveScope = async (scope: "provider" | "user") => {
    setSaving(true);
    try {
      const body = scope === "provider"
        ? { scope, providerConfigId: providerId, perRequestCostLimitEnabled: providerEnabled, perRequestCostLimitUsd: providerAmount || null }
        : { scope, userId, perRequestCostLimitEnabled: userEnabled, perRequestCostLimitUsd: userAmount || null };
      await api("/api/ai/budgets", { method: "PUT", headers: { "content-type": "application/json" }, body: JSON.stringify(body) });
      await onSaved();
      announce(`${scope === "provider" ? "Provider" : "User"} per-request limit saved. New requests use it immediately.`);
    } catch (cause) { announce((cause as Error).message, true); }
    finally { setSaving(false); }
  };
  return <section className={styles.twoColumn}><article className="glass-panel"><h2>Provider per-request limit</h2><p>A provider limit applies only when that provider is selected.</p><label>Provider<select value={providerId} onChange={(event) => chooseProvider(event.target.value)}><option value="">Choose provider</option>{providers.map((provider) => <option key={provider.id} value={provider.id}>{provider.displayName}</option>)}</select></label><label className={styles.check}><input type="checkbox" checked={providerEnabled} onChange={(event) => setProviderEnabled(event.target.checked)}/>Enforce provider limit</label><label>Amount (USD)<input aria-label="Provider per-request cost limit amount" type="number" min="0.000001" step="0.000001" disabled={!providerEnabled} value={providerAmount} onChange={(event) => setProviderAmount(event.target.value)}/><small>{providerEnabled ? invalid(providerEnabled, providerAmount) ? "Enter an amount greater than zero." : `Provider override: USD ${Number(providerAmount).toFixed(6)}` : "Disabled / Inherit broader policy"}</small></label><button disabled={!providerId || saving || invalid(providerEnabled, providerAmount)} onClick={() => void saveScope("provider")}>Save provider limit</button></article><article className="glass-panel"><h2>User per-request limit</h2><p>A user limit participates with global and selected-provider limits; the strictest enabled value wins.</p><label>User<select value={userId} onChange={(event) => chooseUser(event.target.value)}><option value="">Choose user</option>{users.map((user) => <option key={user.id} value={user.id}>{user.username}{user.email ? ` · ${user.email}` : ""}</option>)}</select></label><label className={styles.check}><input type="checkbox" checked={userEnabled} onChange={(event) => setUserEnabled(event.target.checked)}/>Enforce user limit</label><label>Amount (USD)<input aria-label="User per-request cost limit amount" type="number" min="0.000001" step="0.000001" disabled={!userEnabled} value={userAmount} onChange={(event) => setUserAmount(event.target.value)}/><small>{userEnabled ? invalid(userEnabled, userAmount) ? "Enter an amount greater than zero." : `User override: USD ${Number(userAmount).toFixed(6)}` : "Disabled / Inherit broader policy"}</small></label><button disabled={!userId || saving || invalid(userEnabled, userAmount)} onClick={() => void saveScope("user")}>Save user limit</button></article></section>;
}

export default function AiGovernanceDashboard() {
  const [section, setSection] = useState<(typeof sections)[number]>("Overview"); const [governance, setGovernance] = useState<Row | null>(null); const [usage, setUsage] = useState<Row | null>(null); const [providers, setProviders] = useState<Row[]>([]); const [pricing, setPricing] = useState<Row[]>([]); const [budgets, setBudgets] = useState<Row>({ providers: [], users: [], availableUsers: [] }); const [comparisons, setComparisons] = useState<Row[]>([]); const [alerts, setAlerts] = useState<Row>({ thresholds: [], events: [] }); const [preview, setPreview] = useState<Row | null>(null); const [busy, setBusy] = useState(false); const [message, setMessage] = useState(""); const [error, setError] = useState(""); const [formDirty, setFormDirty] = useState(false);
  const [pricingForm, setPricingForm] = useState<Row>({ providerConfigId: "", modelIdentifier: "", displayName: "", inputPricePerMillion: "", outputPricePerMillion: "", fixedRequestCost: "", currency: "USD", billingClassification: "EXTERNAL", status: "PRICED", estimated: true });
  const [previewForm, setPreviewForm] = useState<Row>({ providerId: "", model: "", privacyMode: "METADATA_LIMITED", maxOutputTokens: 500 });
  const announce = (text: string, failed = false) => { setMessage(failed ? "" : text); setError(failed ? text : ""); };
  const load = useCallback(async () => { setBusy(true); try { const [g, u, p, prices, limits, compare, alertData] = await Promise.all([api("/api/ai/governance"), api("/api/ai/usage"), api("/api/ai/providers"), api("/api/ai/pricing"), api("/api/ai/budgets"), api("/api/ai/compare"), api("/api/ai/alerts")]); setGovernance(g); setUsage(u); setProviders(p.providers || []); setPricing(prices.profiles || []); setBudgets(limits); setComparisons(compare.comparisons || []); setAlerts(alertData); setPreviewForm((current) => ({ ...current, providerId: current.providerId || p.providers?.[0]?.id || "", model: current.model || p.providers?.[0]?.defaultModel || "" })); } catch (cause) { announce((cause as Error).message, true); } finally { setBusy(false); } }, []);
  useEffect(() => { void load(); }, [load]);
  async function saveGovernance(changes: Row, confirmation?: string) { if (confirmation && !confirm(confirmation)) return; setBusy(true); try { await api("/api/ai/governance", { method: "PATCH", headers: { "content-type": "application/json" }, body: JSON.stringify(changes) }); announce("AI governance settings saved and added to the administrative audit log."); await load(); } catch (cause) { announce((cause as Error).message, true); } finally { setBusy(false); } }
  function edit(key: string, value: unknown) { setGovernance((current) => current ? { ...current, [key]: value } : current); }
  async function runPreview() { setBusy(true); try { const provider = providers.find((row) => row.id === previewForm.providerId); const result = await api("/api/ai/preview", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ ...previewForm, model: previewForm.model || provider?.defaultModel, featureKey: "administrative_policy_test", messages: [{ role: "user", content: "Analyze the provider-safe music attributes for an administrative policy test." }], metadataRecords: [{ artist: "Massive Attack", title: "Teardrop", album: "Mezzanine", genres: ["trip hop"], release_year: 1998, bpm: 76, energy: 0.25, file_path: "/private/music.flac", plex_rating_key: "private-id", playlist_owner: "private-user" }] }) }); setPreview(result); announce("Preview resolved without contacting the provider."); } catch (cause) { setPreview(null); announce((cause as Error).message, true); } finally { setBusy(false); } }
  async function acknowledgeFull(accepted: boolean) { if (accepted && !confirm("Full Metadata may send administrator-approved music metadata to external providers. Secrets and infrastructure fields remain blocked. Accept this versioned warning?")) return; try { await api("/api/ai/governance", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ accepted }) }); await load(); announce(accepted ? "Full Metadata warning accepted." : "Full Metadata acceptance revoked."); } catch (cause) { announce((cause as Error).message, true); } }
  async function addPricing() { setBusy(true); try { await api("/api/ai/pricing", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ ...pricingForm, inputPricePerMillion: pricingForm.status === "UNPRICED" || pricingForm.inputPricePerMillion === "" ? null : pricingForm.inputPricePerMillion, outputPricePerMillion: pricingForm.status === "UNPRICED" || pricingForm.outputPricePerMillion === "" ? null : pricingForm.outputPricePerMillion, fixedRequestCost: pricingForm.fixedRequestCost === "" ? null : pricingForm.fixedRequestCost }) }); setPricingForm({ ...pricingForm, modelIdentifier: "", displayName: "" }); await load(); announce("Pricing profile added."); } catch (cause) { announce((cause as Error).message, true); } finally { setBusy(false); } }
  async function applyUsageFilters(filters: Row) { try { const query = new URLSearchParams(Object.entries(filters).filter(([, value]) => value != null && value !== "").map(([key, value]) => [key, String(value)])).toString(); setUsage(await api(`/api/ai/usage?${query}`)); announce("Usage filters applied."); } catch (cause) { announce((cause as Error).message, true); } }
  async function importDiscoveredModels() { if (!pricingForm.providerConfigId) return; try { const result = await api("/api/ai/pricing", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ importProviderModels: pricingForm.providerConfigId }) }); await load(); announce(`${result.imported} discovered model names imported as disabled, unpriced profiles.`); } catch (cause) { announce((cause as Error).message, true); } }
  const activeWarnings = alerts.events?.filter((row: Row) => !row.acknowledgedAt) || []; const budgetPercent = Number(usage?.budget?.percentConsumed || 0) * 100;
  const comparisonRows = useMemo(() => comparisons.slice(0, 100), [comparisons]);
  if (busy && !governance) return <div className={styles.loading}><Loader2 className={styles.spin}/> Loading AI governance controls…</div>;
  return <main className={styles.wrapper}>
    <header className={styles.header}><div><h1><ShieldCheck/> AI Governance</h1><p>Privacy, spending, token, provider, background activity, retry, and auditing controls for every AI request.</p></div><span data-state={governance?.reviewed && !formDirty && !error ? "ready" : "review"}>{governance?.reviewed && !formDirty && !error ? "Policy reviewed" : formDirty ? "Unsaved changes" : "Review required"}</span></header>
    <div className={styles.live} aria-live="polite">{message || error}</div>{error && <div className={styles.error} role="alert"><AlertTriangle/>{error}</div>}{message && <div className={styles.success}><CheckCircle2/>{message}</div>}
    {!governance?.reviewed && <section className={styles.setup} role="alert"><LockKeyhole/><div><h2>Review required after upgrade</h2><p>Until review, Mixarr uses Metadata Limited, a restrictive allowlist, no paid fallback, no external background AI, and blocks unpriced external models.</p><button onClick={() => void saveGovernance({ reviewed: true })}>Mark policy reviewed</button></div></section>}
    <nav className={styles.tabs} aria-label="AI governance sections">{sections.map((item) => <button key={item} aria-current={section === item ? "page" : undefined} onClick={() => setSection(item)}>{item}</button>)}</nav>
    {section === "Budgets" && <GlobalPerRequestLimit governance={governance} edit={edit} save={saveGovernance} busy={busy}/>}
    {section === "Budgets" && <ScopedPerRequestLimitEditors providers={providers} providerPolicies={budgets.providers || []} users={budgets.availableUsers || []} userPolicies={budgets.users || []} onSaved={load} announce={announce}/>}
    {section === "Privacy" && <section className="glass-panel"><h2>Secure debugging</h2><div className={styles.notice}><AlertTriangle/><p>Provider-safe payload samples can still contain identifying music metadata. Recording is off by default and expires automatically.</p></div><label className={styles.check}><input type="checkbox" checked={!!governance?.secureDebugEnabled} onChange={(event) => void saveGovernance({ secureDebugEnabled: event.target.checked }, event.target.checked ? "Temporarily store sanitized AI payload samples for debugging?" : undefined)}/>Enable sanitized-payload recording</label><label>Retention hours<input type="number" min="1" max="168" value={governance?.secureDebugRetentionHours || 24} onChange={(event) => edit("secureDebugRetentionHours", Number(event.target.value))} onBlur={() => void saveGovernance({ secureDebugRetentionHours: governance?.secureDebugRetentionHours })}/></label></section>}
    {section === "Alerts" && <AlertEditor onSaved={load} announce={announce}/>}
    {section === "Models & Pricing" && <section className="glass-panel"><h2>Import discovered model names</h2><p>Choose a provider in the pricing editor, then import its discovered model names as disabled, unpriced profiles for administrator review.</p><button disabled={!pricingForm.providerConfigId} onClick={() => void importDiscoveredModels()}>Import discovered names</button></section>}

    {section === "Overview" && <><section className={styles.cards} aria-label="AI governance overview"><article><span>Requests</span><strong>{number(usage?.summary?.requests)}</strong></article><article><span>Estimated cost</span><strong>{money(usage?.summary?.estimatedCost, governance?.currency)}</strong></article><article><span>Remaining budget</span><strong>{money(usage?.summary?.remainingBudget, governance?.currency)}</strong></article><article><span>Reserved in flight</span><strong>{money(usage?.summary?.reservedCost, governance?.currency)}</strong></article><article><span>Local / external</span><strong>{number(usage?.summary?.localRequests)} / {number(usage?.summary?.externalRequests)}</strong></article><article><span>Blocked</span><strong>{number(usage?.summary?.blockedRequests)}</strong></article></section><section className={styles.twoColumn}><article className="glass-panel"><h2><WalletCards/> Budget status</h2><div className={styles.progress} aria-label={`${budgetPercent.toFixed(1)} percent of budget consumed`}><span style={{ width: `${Math.min(100, budgetPercent)}%` }}/></div><p>{money(usage?.budget?.usage, governance?.currency)} of {money(usage?.budget?.limit, governance?.currency)} used · {budgetPercent.toFixed(1)}%</p><p>Projected at reset: {money(usage?.budget?.projectedEndOfPeriod, governance?.currency)} <em>(estimate)</em></p><p>Hard shutdown: {usage?.budget?.hardShutdownEnabled ? "Enabled" : "Disabled"} · Next reset: {usage?.budget?.resetAt ? new Date(usage.budget.resetAt).toLocaleDateString() : "—"}</p></article><article className="glass-panel"><h2><Bot/> Policy status</h2><dl className={styles.statusList}><div><dt>Privacy</dt><dd>{String(governance?.privacyMode || "").replaceAll("_", " ")}</dd></div><div><dt>Paid fallback</dt><dd>{governance?.allowPaidProviderFallback ? "Allowed" : "Blocked"}</dd></div><div><dt>Background AI</dt><dd>{governance?.backgroundAiEnabled ? "Enabled" : "Disabled"}</dd></div><div><dt>Unpriced external models</dt><dd>{governance?.allowUnpricedExternalModels ? "Allowed" : "Blocked"}</dd></div><div><dt>Active warnings</dt><dd>{activeWarnings.length}</dd></div></dl></article></section></>}

    {section === "Providers" && <AiProviderDashboard/>}
    {section === "Security & Queue" && <AiSecurityDashboard/>}

    {section === "Models & Pricing" && <><section className="glass-panel"><h2>Manual pricing profile</h2><p>Prices are configuration, not permanent application logic. Values are per one million tokens and estimates remain clearly labeled.</p><div className={styles.formGrid}><label>Provider<select value={pricingForm.providerConfigId} onChange={(event) => setPricingForm({ ...pricingForm, providerConfigId: event.target.value })}><option value="">Choose provider</option>{providers.map((row) => <option key={row.id} value={row.id}>{row.displayName}</option>)}</select></label><label>Model identifier<input value={pricingForm.modelIdentifier} onChange={(event) => setPricingForm({ ...pricingForm, modelIdentifier: event.target.value, displayName: pricingForm.displayName || event.target.value })}/></label><label>Display name<input value={pricingForm.displayName} onChange={(event) => setPricingForm({ ...pricingForm, displayName: event.target.value })}/></label><label>Status<select value={pricingForm.status} onChange={(event) => setPricingForm({ ...pricingForm, status: event.target.value })}><option>PRICED</option><option>FREE</option><option>UNPRICED</option></select></label><label>Input price<input type="number" min="0" step="0.000001" value={pricingForm.inputPricePerMillion} onChange={(event) => setPricingForm({ ...pricingForm, inputPricePerMillion: event.target.value })}/></label><label>Output price<input type="number" min="0" step="0.000001" value={pricingForm.outputPricePerMillion} onChange={(event) => setPricingForm({ ...pricingForm, outputPricePerMillion: event.target.value })}/></label><label>Fixed request cost<input type="number" min="0" step="0.000001" value={pricingForm.fixedRequestCost} onChange={(event) => setPricingForm({ ...pricingForm, fixedRequestCost: event.target.value })}/></label><label>Billing<select value={pricingForm.billingClassification} onChange={(event) => setPricingForm({ ...pricingForm, billingClassification: event.target.value })}><option>EXTERNAL</option><option>LOCAL</option><option>FREE</option></select></label></div><button disabled={!pricingForm.providerConfigId || !pricingForm.modelIdentifier || !pricingForm.displayName} onClick={() => void addPricing()}>Add pricing profile</button></section><DataTable headings={["Provider", "Model", "Input / 1M", "Output / 1M", "Fixed", "Status", "Verified"]} rows={pricing.map((row) => [row.provider?.displayName, row.modelIdentifier, money(row.inputPricePerMillion, row.currency), money(row.outputPricePerMillion, row.currency), money(row.fixedRequestCost, row.currency), `${row.status}${row.estimated ? " · estimated" : ""}`, row.lastVerifiedAt ? new Date(row.lastVerifiedAt).toLocaleDateString() : "Not verified"])} empty="No pricing profiles configured."/><section className="glass-panel"><h2>Provider cost comparison</h2><p>Cost is shown separately from capabilities and quality. Cheapest does not mean best.</p><DataTable headings={["Provider", "Model", "Location", "Expected estimate", "Context", "Health", "Privacy"]} rows={comparisonRows.map((row) => [row.provider, row.model, row.local ? "Local" : "External", row.cost ? money(row.cost.expectedEstimatedCost, row.cost.currency) : "Unpriced", number(row.contextWindow), row.healthStatus, row.privacyEligible ? "Eligible" : "Blocked"])} empty="Discover models to compare them."/></section></>}

    {section === "Privacy" && <><section className="glass-panel"><h2>Privacy mode</h2><label>Global privacy policy<select value={governance?.privacyMode || "METADATA_LIMITED"} onChange={(event) => { const next = event.target.value; if ((next === "FULL_METADATA" || next === "METADATA_LIMITED") && !confirm("This change can allow more metadata to leave the local network. Continue?")) return; edit("privacyMode", next); void saveGovernance({ privacyMode: next }); }}><option value="LOCAL_ONLY">Local Only</option><option value="ANONYMOUS_METADATA">Anonymous Metadata</option><option value="METADATA_LIMITED">Metadata Limited</option><option value="FULL_METADATA" disabled={!governance?.fullMetadataAcknowledged}>Full Metadata</option></select><small>The strictest global, feature, and user policy wins. Features cannot silently weaken this setting.</small></label><div className={styles.notice}><AlertTriangle/><p>Anonymous attributes can still identify recordings in combination. “Full” never includes secrets, paths, credentials, raw files, or infrastructure identifiers.</p></div><label className={styles.check}><input type="checkbox" checked={!!governance?.fullMetadataAcknowledged} onChange={(event) => void acknowledgeFull(event.target.checked)}/>Accept versioned Full Metadata warning ({governance?.fullMetadataPolicyVersion})</label></section><section className="glass-panel"><h2>External metadata allowlist</h2><div className={styles.checkboxGrid}>{metadataFields.map((field) => <label key={field}><input type="checkbox" checked={(governance?.metadataAllowlist || []).includes(field)} onChange={(event) => { const set = new Set(governance?.metadataAllowlist || []); event.target.checked ? set.add(field) : set.delete(field); const list = Array.from(set); edit("metadataAllowlist", list); void saveGovernance({ metadataAllowlist: list }); }}/>{field.replaceAll("_", " ")}</label>)}</div><div className={styles.formGrid}><label>Anonymization granularity<select value={governance?.anonymousGranularity || "STRICT"} onChange={(event) => { edit("anonymousGranularity", event.target.value); void saveGovernance({ anonymousGranularity: event.target.value }); }}><option>STRICT</option><option>BALANCED</option><option>MINIMAL</option></select></label><label>Year band size<input type="number" min="5" max="50" value={governance?.anonymousYearBandSize || 10} onChange={(event) => edit("anonymousYearBandSize", Number(event.target.value))} onBlur={() => void saveGovernance({ anonymousYearBandSize: governance?.anonymousYearBandSize })}/></label><label>BPM band size<input type="number" min="5" max="50" value={governance?.anonymousBpmBandSize || 10} onChange={(event) => edit("anonymousBpmBandSize", Number(event.target.value))} onBlur={() => void saveGovernance({ anonymousBpmBandSize: governance?.anonymousBpmBandSize })}/></label></div></section><section className="glass-panel"><h2>Outgoing metadata and cost preview</h2><div className={styles.formGrid}><label>Provider<select value={previewForm.providerId} onChange={(event) => { const provider = providers.find((row) => row.id === event.target.value); setPreviewForm({ ...previewForm, providerId: event.target.value, model: provider?.defaultModel || "" }); }}><option value="">Choose provider</option>{providers.map((row) => <option key={row.id} value={row.id}>{row.displayName}</option>)}</select></label><label>Model<input value={previewForm.model} onChange={(event) => setPreviewForm({ ...previewForm, model: event.target.value })}/></label><label>Requested mode<select value={previewForm.privacyMode} onChange={(event) => setPreviewForm({ ...previewForm, privacyMode: event.target.value })}><option>LOCAL_ONLY</option><option>ANONYMOUS_METADATA</option><option>METADATA_LIMITED</option><option>FULL_METADATA</option></select></label></div><button disabled={!previewForm.providerId || !previewForm.model} onClick={() => void runPreview()}><Eye/> Preview only</button><AiRequestPreview preview={preview}/></section></>}

    {section === "Budgets" && <><SettingsPanel title="Global budget" description="Reservations count before dispatch so concurrent requests cannot collectively cross a hard limit." governance={governance} fields={[{ key: "monthlyBudget", label: "Monthly limit", type: "number" }, { key: "budgetResetDay", label: "Reset day (1–28)", type: "number" }, { key: "currency", label: "Currency", type: "text" }]} edit={edit}/><section className="glass-panel"><label className={styles.check}><input type="checkbox" checked={governance?.hardShutdownEnabled !== false} onChange={(event) => void saveGovernance({ hardShutdownEnabled: event.target.checked }, event.target.checked ? undefined : "Disabling hard shutdown can permit charges above the configured budget. Continue?")}/>Hard shutdown enabled</label><label className={styles.check}><input type="checkbox" checked={!!governance?.allowUnpricedExternalModels} onChange={(event) => void saveGovernance({ allowUnpricedExternalModels: event.target.checked })}/>Allow unpriced external models</label><label className={styles.check}><input type="checkbox" checked={!!governance?.paidProvidersAllowed} onChange={(event) => void saveGovernance({ paidProvidersAllowed: event.target.checked })}/>Permit paid providers globally</label><label className={styles.check}><input type="checkbox" checked={governance?.allowUserPaidProviderOverrides !== false} onChange={(event) => void saveGovernance({ allowUserPaidProviderOverrides: event.target.checked })}/>Allow user-level paid-provider overrides</label><label className={styles.check}><input type="checkbox" checked={!!governance?.automaticCheaperModelFallback} onChange={(event) => void saveGovernance({ automaticCheaperModelFallback: event.target.checked })}/>Automatically use a cheaper compatible model at budget warnings or hard limits</label><label className={styles.check}><input type="checkbox" checked={!!governance?.allowPaidProviderFallback} onChange={(event) => void saveGovernance({ allowPaidProviderFallback: event.target.checked }, event.target.checked ? "Paid fallback can create external charges. Continue?" : undefined)}/>Allow fallback to paid providers</label><button disabled={busy} onClick={() => void saveGovernance({ monthlyBudget: governance?.monthlyBudget == null || governance.monthlyBudget === "" ? null : governance.monthlyBudget, budgetResetDay: Number(governance?.budgetResetDay), currency: governance?.currency, hardShutdownEnabled: governance?.hardShutdownEnabled })}>Save budget settings</button></section><BudgetEditors providers={providers} availableUsers={budgets.availableUsers || []} policies={budgets.users || []} onSaved={load} announce={announce} onDirty={setFormDirty} onValidationError={() => setSection("Budgets")}/><DataTable headings={["Provider", "Daily", "Monthly", "Hard limit", "Fallback after exhausted"]} rows={(budgets.providers || []).map((row: Row) => [row.provider?.displayName, money(row.dailyLimit, row.currency), money(row.monthlyLimit, row.currency), row.hardLimitEnabled ? "Yes" : "No", row.allowFallbackWhenExhausted ? "Yes" : "No"])} empty="No provider-specific budgets configured."/><DataTable headings={["User", "Daily", "Monthly", "Requests/day", "Paid providers"]} rows={(budgets.users || []).map((row: Row) => [row.userId, money(row.dailyCostLimit, row.currency), money(row.monthlyCostLimit, row.currency), row.dailyRequestLimit ?? "—", row.paidProvidersAllowed == null ? "Inherit" : row.paidProvidersAllowed ? "Allowed" : "Blocked"])} empty="No user-specific overrides configured."/><DataTable headings={["Request", "Provider", "Reserved", "Expires"]} rows={(governance?.reservations || []).map((row: Row) => [row.requestId, providers.find((provider) => provider.id === row.providerConfigId)?.displayName || row.providerConfigId, money(row.reservedCost, row.currency), new Date(row.expiresAt).toLocaleString()])} empty="No in-flight reservations."/></>}

    {section === "Token Limits" && <><SettingsPanel title="Prompt and token limits" description="The strictest global, provider, model, feature, user, and request limit wins." governance={governance} fields={[{ key: "maximumInputTokens", label: "Maximum input tokens", type: "number" }, { key: "maximumOutputTokens", label: "Maximum output tokens", type: "number" }, { key: "maximumCombinedTokens", label: "Maximum combined tokens", type: "number" }, { key: "maximumPromptCharacters", label: "Maximum prompt characters", type: "number" }, { key: "maximumPromptBytes", label: "Maximum prompt bytes", type: "number" }, { key: "maximumMetadataRecords", label: "Maximum metadata records", type: "number" }, { key: "maximumContextMessages", label: "Maximum context messages", type: "number" }, { key: "maximumResponseBytes", label: "Maximum response bytes", type: "number" }, { key: "maximumStructuredItems", label: "Maximum structured items", type: "number" }]} edit={edit}/><section className="glass-panel"><label>Oversized context policy<select value={governance?.defaultContextTrimmingStrategy || "REJECT"} onChange={(event) => edit("defaultContextTrimmingStrategy", event.target.value)}><option value="REJECT">Reject oversized request</option><option value="REMOVE_OLDEST">Remove oldest context</option><option value="REMOVE_LOWEST_PRIORITY">Remove lowest-priority context</option><option value="REMOVE_DUPLICATES">Remove duplicate context</option></select></label><button onClick={() => void saveGovernance({ maximumInputTokens: Number(governance?.maximumInputTokens), maximumOutputTokens: Number(governance?.maximumOutputTokens), maximumCombinedTokens: Number(governance?.maximumCombinedTokens), maximumPromptCharacters: Number(governance?.maximumPromptCharacters), maximumPromptBytes: Number(governance?.maximumPromptBytes), maximumMetadataRecords: Number(governance?.maximumMetadataRecords), maximumContextMessages: Number(governance?.maximumContextMessages), maximumResponseBytes: Number(governance?.maximumResponseBytes), maximumStructuredItems: Number(governance?.maximumStructuredItems), defaultContextTrimmingStrategy: governance?.defaultContextTrimmingStrategy })}>Save token limits</button></section><ModelTokenLimitEditor providers={providers} announce={announce}/></>}

    {section === "Background Requests" && <section className="glass-panel"><h2>Background AI policy</h2><p>Queued work is re-evaluated immediately before execution and cannot retain an older, weaker policy.</p><label className={styles.check}><input type="checkbox" checked={!!governance?.backgroundAiEnabled} onChange={(event) => void saveGovernance({ backgroundAiEnabled: event.target.checked })}/>Enable background AI globally</label><label className={styles.check}><input type="checkbox" checked={!!governance?.externalBackgroundAiEnabled} onChange={(event) => void saveGovernance({ externalBackgroundAiEnabled: event.target.checked }, event.target.checked ? "External background AI may transmit metadata and create charges without an active foreground request. Continue?" : undefined)}/>Enable paid or external background AI</label><label className={styles.check}><input type="checkbox" checked={governance?.requireExternalBackgroundApproval !== false} onChange={(event) => void saveGovernance({ requireExternalBackgroundApproval: event.target.checked })}/>Require manual approval for external background requests</label><div className={styles.formGrid}><label>Requests per day<input type="number" min="1" value={governance?.maximumBackgroundRequestsPerDay || ""} onChange={(event) => edit("maximumBackgroundRequestsPerDay", event.target.value ? Number(event.target.value) : null)}/></label><label>Cost per day<input type="number" min="0" step="0.01" value={governance?.maximumBackgroundCostPerDay || ""} onChange={(event) => edit("maximumBackgroundCostPerDay", event.target.value || null)}/></label><label>Maximum concurrency<input type="number" min="1" max="100" value={governance?.maximumBackgroundConcurrency || 1} onChange={(event) => edit("maximumBackgroundConcurrency", Number(event.target.value))}/></label></div><button onClick={() => void saveGovernance({ maximumBackgroundRequestsPerDay: governance?.maximumBackgroundRequestsPerDay, maximumBackgroundCostPerDay: governance?.maximumBackgroundCostPerDay, maximumBackgroundConcurrency: governance?.maximumBackgroundConcurrency })}>Save background limits</button></section>}

    {section === "Timeouts & Retries" && <><SettingsPanel title="Timeout policy" description="The strictest applicable timeout is enforced." governance={governance} fields={[{ key: "connectionTimeoutMs", label: "Connection timeout (ms)", type: "number" }, { key: "firstTokenTimeoutMs", label: "First-token timeout (ms)", type: "number" }, { key: "totalRequestTimeoutMs", label: "Total timeout (ms)", type: "number" }, { key: "streamingIdleTimeoutMs", label: "Streaming idle timeout (ms)", type: "number" }, { key: "cancellationGraceMs", label: "Cancellation grace (ms)", type: "number" }]} edit={edit}/><section className="glass-panel"><h2>Retry cost protection</h2><p>Retry cost is checked only after a transient provider failure. Blank means no monetary retry limit; zero permits only zero-cost retries. Zero retry attempts disables retries.</p><div className={styles.formGrid}><label>Maximum retry attempts<input type="number" min="0" max="10" value={governance?.maximumRetryAttempts ?? 1} onChange={(event) => edit("maximumRetryAttempts", Number(event.target.value))}/></label><label>Maximum retry cost<input type="number" min="0" step="0.000001" value={governance?.maximumRetryCost ?? ""} onChange={(event) => edit("maximumRetryCost", event.target.value === "" ? null : event.target.value)}/></label><label>Maximum cumulative request cost<input type="number" min="0" step="0.000001" value={governance?.maximumCumulativeRequestCost ?? ""} onChange={(event) => edit("maximumCumulativeRequestCost", event.target.value === "" ? null : event.target.value)}/></label></div><label className={styles.check}><input type="checkbox" checked={!!governance?.retryAfterPossibleBilling} onChange={(event) => void saveGovernance({ retryAfterPossibleBilling: event.target.checked }, event.target.checked ? "The provider may charge for both the original request and retry. Continue?" : undefined)}/>Retry after a request may have been billed</label><button onClick={() => void saveGovernance({ connectionTimeoutMs: Number(governance?.connectionTimeoutMs), firstTokenTimeoutMs: Number(governance?.firstTokenTimeoutMs), totalRequestTimeoutMs: Number(governance?.totalRequestTimeoutMs), streamingIdleTimeoutMs: Number(governance?.streamingIdleTimeoutMs), cancellationGraceMs: Number(governance?.cancellationGraceMs), maximumRetryAttempts: Number(governance?.maximumRetryAttempts), maximumRetryCost: governance?.maximumRetryCost, maximumCumulativeRequestCost: governance?.maximumCumulativeRequestCost })}>Save timeout and retry policy</button></section></>}

    {section === "Alerts" && <><section className="glass-panel"><h2>Active administrative warnings</h2>{!activeWarnings.length ? <div className={styles.empty}><CheckCircle2/><p>No active AI governance warnings.</p></div> : activeWarnings.map((row: Row) => <article className={styles.alert} key={row.id}><AlertTriangle/><div><strong>{row.condition.replaceAll("_", " ")}</strong><p>{row.scopeType} · {new Date(row.createdAt).toLocaleString()}</p></div></article>)}</section><DataTable headings={["Scope", "Condition", "Thresholds", "Cooldown", "Enabled"]} rows={(alerts.thresholds || []).map((row: Row) => [row.scopeType, row.condition, (row.thresholdsJson || []).join(", "), `${row.cooldownMinutes} minutes`, row.enabled ? "Yes" : "No"])} empty="Default global budget thresholds are 50%, 75%, 90%, and 100%."/></>}

    {section === "Usage & Audit" && <><section className={styles.cards}><article><span>Successful</span><strong>{number(usage?.summary?.successfulRequests)}</strong></article><article><span>Failed</span><strong>{number(usage?.summary?.failedRequests)}</strong></article><article><span>Blocked</span><strong>{number(usage?.summary?.blockedRequests)}</strong></article><article><span>Input tokens</span><strong>≈ {number(usage?.summary?.inputTokens)}</strong></article><article><span>Output tokens</span><strong>≈ {number(usage?.summary?.outputTokens)}</strong></article><article><span>Total tokens</span><strong>≈ {number(usage?.summary?.totalTokens)}</strong></article></section><UsageFilters providers={providers} onApply={applyUsageFilters}/><div className={styles.actions}><a href="/api/ai/usage/export?format=csv"><Download/> Export CSV</a><a href="/api/ai/usage/export?format=json"><Download/> Export JSON</a><button onClick={() => void load()}><RefreshCw/> Refresh</button></div><section className="glass-panel"><h2><BarChart3/> Daily usage</h2><div className={styles.chart}>{(usage?.charts?.daily || []).map((row: Row) => <div key={row.date}><span>{new Date(`${row.date}T00:00:00`).toLocaleDateString(undefined, { month: "short", day: "numeric" })}</span><i style={{ height: `${Math.max(4, Math.min(120, row.requests * 5))}px` }} title={`${row.requests} requests`}/><small>{row.requests}</small></div>)}</div></section><DataTable headings={["Date & time", "Feature", "User", "Provider", "Model", "Privacy", "Input", "Output", "Cost", "Duration", "Status", "Fallback"]} rows={(usage?.records || []).map((row: Row) => [new Date(row.createdAt).toLocaleString(), row.featureKey, row.userId || "System", row.providerDisplayName || "—", row.model || "—", row.privacyMode?.replaceAll("_", " ") || "—", row.inputTokenCount == null ? "—" : `≈ ${number(row.inputTokenCount)}`, row.outputTokenCount == null ? "—" : `≈ ${number(row.outputTokenCount)}`, money(row.actualCost ?? row.estimatedCost, governance?.currency), row.latencyMs == null ? "—" : `${row.latencyMs} ms`, row.status, row.fallbackReason ? "Yes" : "No"])} empty="No AI requests match the current period."/></>}
  </main>;
}

function SettingsPanel({ title, description, governance, fields, edit }: { title: string; description: string; governance: Row | null; fields: Array<{ key: string; label: string; type: string }>; edit: (key: string, value: unknown) => void }) { return <section className="glass-panel"><h2>{title}</h2><p>{description}</p><div className={styles.formGrid}>{fields.map((field) => <label key={field.key}>{field.label}<input type={field.type} value={governance?.[field.key] ?? ""} onChange={(event) => edit(field.key, field.type === "number" ? (event.target.value ? Number(event.target.value) : null) : event.target.value)}/></label>)}</div></section>; }
function ModelTokenLimitEditor({ providers, announce }: { providers: Row[]; announce: (text: string, failed?: boolean) => void }) { const [providerId, setProviderId] = useState(""); const [models, setModels] = useState<Row[]>([]); const [form, setForm] = useState<Row>({ modelIdentifier: "", maximumInputTokens: "", maximumOutputTokens: "", maximumCombinedTokens: "" }); const selectProvider = async (id: string) => { setProviderId(id); setForm({ modelIdentifier: "", maximumInputTokens: "", maximumOutputTokens: "", maximumCombinedTokens: "" }); if (!id) return setModels([]); try { const result = await api(`/api/ai/providers/${id}/models`); setModels(result.models || []); } catch (cause) { announce((cause as Error).message, true); } }; const selectModel = (identifier: string) => { const model = models.find((row) => row.modelIdentifier === identifier); setForm({ modelIdentifier: identifier, maximumInputTokens: model?.maximumInputTokens ?? "", maximumOutputTokens: model?.maximumOutputTokens ?? "", maximumCombinedTokens: model?.maximumCombinedTokens ?? "" }); }; const save = async () => { try { const nullableNumber = (value: unknown) => value === "" ? null : Number(value); await api(`/api/ai/providers/${providerId}/models`, { method: "PATCH", headers: { "content-type": "application/json" }, body: JSON.stringify({ modelIdentifier: form.modelIdentifier, maximumInputTokens: nullableNumber(form.maximumInputTokens), maximumOutputTokens: nullableNumber(form.maximumOutputTokens), maximumCombinedTokens: nullableNumber(form.maximumCombinedTokens) }) }); await selectProvider(providerId); announce("Model token limits saved and added to the administrative audit log."); } catch (cause) { announce((cause as Error).message, true); } }; return <section className="glass-panel"><h2>Per-model token limits</h2><p>Blank values inherit the provider and global limits. Provider discovery context size remains an additional input ceiling.</p><div className={styles.formGrid}><label>Provider<select value={providerId} onChange={(event) => void selectProvider(event.target.value)}><option value="">Choose provider</option>{providers.map((row) => <option key={row.id} value={row.id}>{row.displayName}</option>)}</select></label><label>Model<select value={form.modelIdentifier} onChange={(event) => selectModel(event.target.value)}><option value="">Choose discovered model</option>{models.map((row) => <option key={row.id} value={row.modelIdentifier}>{row.displayName}</option>)}</select></label><label>Maximum input tokens<input type="number" min="1" value={form.maximumInputTokens} onChange={(event) => setForm({ ...form, maximumInputTokens: event.target.value })}/></label><label>Maximum output tokens<input type="number" min="1" value={form.maximumOutputTokens} onChange={(event) => setForm({ ...form, maximumOutputTokens: event.target.value })}/></label><label>Maximum combined tokens<input type="number" min="2" value={form.maximumCombinedTokens} onChange={(event) => setForm({ ...form, maximumCombinedTokens: event.target.value })}/></label></div><button disabled={!providerId || !form.modelIdentifier} onClick={() => void save()}>Save model token limits</button></section>; }
function BudgetEditors({ providers, availableUsers, policies, onSaved, announce, onDirty, onValidationError }: { providers: Row[]; availableUsers: Row[]; policies: Row[]; onSaved: () => Promise<void>; announce: (text: string, failed?: boolean) => void; onDirty: (dirty: boolean) => void; onValidationError: () => void }) {
  const [provider, setProvider] = useState<Row>({ scope: "provider", providerConfigId: "", currency: "USD", dailyLimit: "", monthlyLimit: "", dailyRequestLimit: "", monthlyRequestLimit: "", hardLimitEnabled: true, selectableAfterWarning: true, allowFallbackWhenExhausted: false });
  const [user, setUser] = useState<Row>({ scope: "user", userId: "", currency: "USD", dailyCostLimit: "", monthlyCostLimit: "", dailyRequestLimit: "", monthlyRequestLimit: "", paidProvidersAllowed: null, backgroundRequestsAllowed: null });
  const [fieldErrors, setFieldErrors] = useState<Record<string, string>>({}); const [saving, setSaving] = useState<"provider" | "user" | null>(null); const userPanel = useRef<HTMLElement>(null);
  const updateUser = (changes: Row) => { const aliases: Row = { userId: "user_uuid", dailyCostLimit: "daily_cost_limit", monthlyCostLimit: "monthly_cost_limit", dailyRequestLimit: "daily_requests", monthlyRequestLimit: "monthly_requests", paidProvidersAllowed: "permit_paid_providers", backgroundRequestsAllowed: "permit_background_requests" }; setUser((current) => ({ ...current, ...changes })); setFieldErrors((current) => { const next = { ...current }; for (const key of Object.keys(changes)) delete next[aliases[key] || key]; return next; }); onDirty(true); };
  const chooseUser = (userId: string) => { const existing = policies.find((row) => row.userId === userId); updateUser({ userId, dailyCostLimit: existing?.dailyCostLimit ?? "", monthlyCostLimit: existing?.monthlyCostLimit ?? "", dailyRequestLimit: existing?.dailyRequestLimit ?? "", monthlyRequestLimit: existing?.monthlyRequestLimit ?? "", paidProvidersAllowed: existing?.paidProvidersAllowed ?? null, backgroundRequestsAllowed: existing?.backgroundRequestsAllowed ?? null }); };
  const scrollToFirstError = (errors: Record<string, string>) => { onValidationError(); const first = Object.keys(errors)[0]; setTimeout(() => { const control = userPanel.current?.querySelector<HTMLElement>(`[data-field="${first}"]`); control?.scrollIntoView({ behavior: "smooth", block: "center" }); control?.focus(); }, 0); };
  const save = async (form: Row) => {
    const kind = form.scope === "provider" ? "provider" : "user"; setSaving(kind);
    try {
      const body = Object.fromEntries(Object.entries(form).map(([key, value]) => [key, value === "" ? null : value]));
      await api("/api/ai/budgets", { method: "PUT", headers: { "content-type": "application/json" }, body: JSON.stringify(body) });
      setFieldErrors({}); await onSaved(); onDirty(false); announce(`${kind === "provider" ? "Provider limits" : "User Limits"} saved successfully.`);
    } catch (cause) {
      const requestError = cause as ApiRequestError; const errors = requestError.fieldErrors || {};
      if (kind === "user" && Object.keys(errors).length) { setFieldErrors(errors); scrollToFirstError(errors); const first = errors[Object.keys(errors)[0]]; announce(`User Limits could not be saved: ${first}`, true); }
      else announce(requestError.message, true);
    } finally { setSaving(null); }
  };
  const error = (field: string) => fieldErrors[field] ? <small id={`user-${field}-error`} className={styles.fieldError} role="alert">{fieldErrors[field]}</small> : null;
  return <section className={styles.twoColumn}><article className="glass-panel"><h2>Provider limits</h2><div className={styles.formGrid}><label>Provider<select value={provider.providerConfigId} onChange={(event) => setProvider({ ...provider, providerConfigId: event.target.value })}><option value="">Choose provider</option>{providers.map((row) => <option key={row.id} value={row.id}>{row.displayName}</option>)}</select></label><label>Daily cost limit<input type="number" min="0" step="0.000001" value={provider.dailyLimit} onChange={(event) => setProvider({ ...provider, dailyLimit: event.target.value })}/></label><label>Monthly cost limit<input type="number" min="0" step="0.000001" value={provider.monthlyLimit} onChange={(event) => setProvider({ ...provider, monthlyLimit: event.target.value })}/></label><label>Daily requests<input type="number" min="0" step="1" value={provider.dailyRequestLimit} onChange={(event) => setProvider({ ...provider, dailyRequestLimit: event.target.value })}/></label></div><label className={styles.check}><input type="checkbox" checked={provider.hardLimitEnabled} onChange={(event) => setProvider({ ...provider, hardLimitEnabled: event.target.checked })}/>Hard provider limit</label><label className={styles.check}><input type="checkbox" checked={provider.allowFallbackWhenExhausted} onChange={(event) => setProvider({ ...provider, allowFallbackWhenExhausted: event.target.checked })}/>Allow eligible fallback when exhausted</label><button disabled={!provider.providerConfigId || saving !== null} onClick={() => void save(provider)}>{saving === "provider" ? "Saving…" : "Save provider limits"}</button></article>
    <article className="glass-panel" ref={userPanel}><h2>User Limits</h2><p>Blank limits inherit the broader policy. Choose Inherit for permission fields to preserve tri-state policy precedence.</p><div className={styles.formGrid}><label>User<select value={availableUsers.some((row) => row.id === user.userId) ? user.userId : ""} onChange={(event) => chooseUser(event.target.value)}><option value="">Search or choose a Mixarr user</option>{availableUsers.map((row) => <option key={row.id} value={row.id}>{row.username}{row.email ? ` · ${row.email}` : ""} · {row.id.slice(0, 8)}…</option>)}</select></label><label>User UUID<input list="mixarr-ai-users" data-field="user_uuid" aria-invalid={!!fieldErrors.user_uuid} aria-describedby={fieldErrors.user_uuid ? "user-user_uuid-error" : undefined} value={user.userId} onChange={(event) => updateUser({ userId: event.target.value })} onBlur={() => { if (availableUsers.some((row) => row.id === user.userId.trim())) chooseUser(user.userId.trim()); }}/><datalist id="mixarr-ai-users">{availableUsers.map((row) => <option key={row.id} value={row.id} label={`${row.username}${row.email ? ` · ${row.email}` : ""} · ${row.id.slice(0, 8)}…`}/>)}</datalist>{error("user_uuid")}</label><label>Daily cost limit<input data-field="daily_cost_limit" aria-invalid={!!fieldErrors.daily_cost_limit} aria-describedby={fieldErrors.daily_cost_limit ? "user-daily_cost_limit-error" : undefined} type="number" min="0" step="0.000001" value={user.dailyCostLimit} onChange={(event) => updateUser({ dailyCostLimit: event.target.value })}/>{error("daily_cost_limit")}</label><label>Monthly cost limit<input data-field="monthly_cost_limit" aria-invalid={!!fieldErrors.monthly_cost_limit} aria-describedby={fieldErrors.monthly_cost_limit ? "user-monthly_cost_limit-error" : undefined} type="number" min="0" step="0.000001" value={user.monthlyCostLimit} onChange={(event) => updateUser({ monthlyCostLimit: event.target.value })}/>{error("monthly_cost_limit")}</label><label>Daily requests<input data-field="daily_requests" aria-invalid={!!fieldErrors.daily_requests} aria-describedby={fieldErrors.daily_requests ? "user-daily_requests-error" : undefined} type="number" min="0" step="1" value={user.dailyRequestLimit} onChange={(event) => updateUser({ dailyRequestLimit: event.target.value })}/>{error("daily_requests")}</label></div><label>Permit paid providers<select data-field="permit_paid_providers" value={user.paidProvidersAllowed == null ? "inherit" : String(user.paidProvidersAllowed)} onChange={(event) => updateUser({ paidProvidersAllowed: event.target.value === "inherit" ? null : event.target.value === "true" })}><option value="inherit">Inherit global policy</option><option value="true">Permit</option><option value="false">Deny</option></select></label><label>Permit background requests<select data-field="permit_background_requests" value={user.backgroundRequestsAllowed == null ? "inherit" : String(user.backgroundRequestsAllowed)} onChange={(event) => updateUser({ backgroundRequestsAllowed: event.target.value === "inherit" ? null : event.target.value === "true" })}><option value="inherit">Inherit global policy</option><option value="true">Permit</option><option value="false">Deny</option></select></label><button disabled={!user.userId.trim() || saving !== null} onClick={() => void save({ ...user, userId: user.userId.trim() })}>{saving === "user" ? "Saving…" : "Save user policy"}</button></article></section>;
}
function UsageFilters({ providers, onApply }: { providers: Row[]; onApply: (filters: Row) => Promise<void> }) { const [filters, setFilters] = useState<Row>({ from: "", to: "", providerId: "", model: "", userId: "", feature: "", privacyMode: "", requestSource: "", location: "", status: "", blockReason: "" }); return <section className="glass-panel"><h2>Usage filters</h2><div className={styles.formGrid}><label>From<input type="date" value={filters.from} onChange={(event) => setFilters({ ...filters, from: event.target.value })}/></label><label>To<input type="date" value={filters.to} onChange={(event) => setFilters({ ...filters, to: event.target.value })}/></label><label>Provider<select value={filters.providerId} onChange={(event) => setFilters({ ...filters, providerId: event.target.value })}><option value="">All providers</option>{providers.map((row) => <option key={row.id} value={row.id}>{row.displayName}</option>)}</select></label><label>Model<input value={filters.model} onChange={(event) => setFilters({ ...filters, model: event.target.value })}/></label><label>User<input value={filters.userId} onChange={(event) => setFilters({ ...filters, userId: event.target.value })}/></label><label>Feature<input value={filters.feature} onChange={(event) => setFilters({ ...filters, feature: event.target.value })}/></label><label>Privacy<select value={filters.privacyMode} onChange={(event) => setFilters({ ...filters, privacyMode: event.target.value })}><option value="">All modes</option><option>LOCAL_ONLY</option><option>ANONYMOUS_METADATA</option><option>METADATA_LIMITED</option><option>FULL_METADATA</option></select></label><label>Source<select value={filters.requestSource} onChange={(event) => setFilters({ ...filters, requestSource: event.target.value })}><option value="">All sources</option><option>FOREGROUND</option><option>BACKGROUND</option><option>CONNECTION_TEST</option><option>MODEL_DISCOVERY</option></select></label><label>Location<select value={filters.location} onChange={(event) => setFilters({ ...filters, location: event.target.value })}><option value="">Local and external</option><option>LOCAL</option><option>EXTERNAL</option></select></label><label>Status<select value={filters.status} onChange={(event) => setFilters({ ...filters, status: event.target.value })}><option value="">All statuses</option><option>COMPLETED</option><option>FAILED</option><option>BLOCKED</option><option>CANCELLED</option><option>TIMED_OUT</option></select></label></div><div className={styles.actions}><button onClick={() => void onApply(filters)}>Apply filters</button><button onClick={() => { const cleared = { from: "", to: "", providerId: "", model: "", userId: "", feature: "", privacyMode: "", requestSource: "", location: "", status: "", blockReason: "" }; setFilters(cleared); void onApply(cleared); }}>Clear</button></div></section>; }
function AlertEditor({ onSaved, announce }: { onSaved: () => Promise<void>; announce: (text: string, failed?: boolean) => void }) { const [form, setForm] = useState<Row>({ scopeType: "GLOBAL", scopeId: "", condition: "BUDGET_PERCENT", thresholds: "0.5,0.75,0.9,1", cooldownMinutes: 1440, enabled: true }); const save = async () => { try { await api("/api/ai/alerts", { method: "PUT", headers: { "content-type": "application/json" }, body: JSON.stringify({ ...form, scopeId: form.scopeId || null, thresholds: String(form.thresholds).split(",").map(Number).filter(Number.isFinite) }) }); await onSaved(); announce("AI alert threshold saved."); } catch (cause) { announce((cause as Error).message, true); } }; return <section className="glass-panel"><h2>Configure alert threshold</h2><div className={styles.formGrid}><label>Scope<select value={form.scopeType} onChange={(event) => setForm({ ...form, scopeType: event.target.value })}><option>GLOBAL</option><option>PROVIDER</option><option>USER</option><option>FEATURE</option></select></label><label>Scope ID<input value={form.scopeId} onChange={(event) => setForm({ ...form, scopeId: event.target.value })} placeholder="Optional for global"/></label><label>Condition<select value={form.condition} onChange={(event) => setForm({ ...form, condition: event.target.value })}>{["BUDGET_PERCENT","REQUEST_LIMIT","COST_SPIKE","UNPRICED_MODEL","LOCAL_ONLY_EXTERNAL_ATTEMPT","PAID_FALLBACK_BLOCKED","HARD_SHUTDOWN","RETRY_COST","LARGE_PROMPT","PROVIDER_TIMEOUT","BACKGROUND_USAGE","STALE_PRICING"].map((condition) => <option key={condition}>{condition}</option>)}</select></label><label>Thresholds (comma separated)<input value={form.thresholds} onChange={(event) => setForm({ ...form, thresholds: event.target.value })}/></label><label>Cooldown minutes<input type="number" min="1" max="43200" value={form.cooldownMinutes} onChange={(event) => setForm({ ...form, cooldownMinutes: Number(event.target.value) })}/></label></div><button onClick={() => void save()}>Add threshold</button></section>; }
function DataTable({ headings, rows, empty }: { headings: string[]; rows: unknown[][]; empty: string }) { if (!rows.length) return <div className={styles.empty}><p>{empty}</p></div>; return <div className={styles.tableWrap}><table><thead><tr>{headings.map((heading) => <th key={heading}>{heading}</th>)}</tr></thead><tbody>{rows.map((row, index) => <tr key={index}>{row.map((cell, cellIndex) => <td key={cellIndex}>{String(cell ?? "—")}</td>)}</tr>)}</tbody></table></div>; }
